from S1E7 import Baratheon, Lannister


class King(Baratheon, Lannister):
    """The one true king - or so he thinks."""

    def get_eyes(self):
        """Return the current eye colour."""
        return self.eyes

    def set_eyes(self, value):
        """Update the eye colour."""
        self.eyes = value

    def get_hairs(self):
        """Return the current hair colour."""
        return self.hairs

    def set_hairs(self, value):
        """Update the hair colour."""
        self.hairs = value
